<script setup>import {Head} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';defineProps({manager:Object,history:Array});</script><template><Head :title="manager.manager_name"/><AppLayout><div class="card overflow-hidden"><div class="bg-[#143c2b] p-8 text-white sm:p-11"><p class="label !text-[#f4d35e]">Manager profile</p><h1 class="mt-3 text-4xl font-black">{{manager.manager_name}}</h1><p class="mt-1 text-white/60">{{manager.team_name}}</p><div class="mt-8 grid grid-cols-2 gap-5 sm:grid-cols-4"><div><span class="label !text-white/50">Total</span><b class="block text-2xl">{{manager.total_points}}</b></div><div><span class="label !text-white/50">Overall rank</span><b class="block text-2xl">{{manager.overall_rank?.toLocaleString()||'—'}}</b></div><div><span class="label !text-white/50">Team value</span><b class="block text-2xl">{{manager.team_value?'£'+(manager.team_value/10).toFixed(1)+'m':'—'}}</b></div><div><span class="label !text-white/50">Gameweeks</span><b class="block text-2xl">{{history.length}}</b></div></div></div><div class="p-6 sm:p-8"><h2 class="text-xl font-black">Season trail</h2><div v-if="history.length" class="mt-5 overflow-x-auto"><table class="w-full min-w-150 text-sm"><thead class="label text-left"><tr><th class="py-3">GW</th><th>Points</th><th>Total</th><th>League rank</th><th>Bench</th><th>Transfers</th><th>Chip</th></tr></thead><tbody><tr v-for="h in history" class="border-t border-black/5 dark:border-white/10"><td class="py-4 font-bold">{{h.gameweek?.number}}</td><td>{{h.points}}</td><td>{{h.total_points}}</td><td>{{h.league_rank}}</td><td>{{h.bench_points}}</td><td>{{h.transfers}} <small v-if="h.transfer_cost">(-{{h.transfer_cost}})</small></td><td>{{h.chip||'—'}}</td></tr></tbody></table></div><p v-else class="mt-5 text-[#718078]">History will build automatically each gameweek.</p></div></div></AppLayout></template>
